80		for _, featureID := range featureIDs {
81			var row database2.WorkspaceFeatureTaskCounts
82			if err := row.FeatureID.Scan(featureID); err != nil {
83				return nil, err
84			}
85			counts[featureID] = row
86		}
87		for _, task := range f.tasks {
88			featureID := database2.UUIDString(task.FeatureID)
89			row, ok := counts[featureID]
90			if !ok {
91				continue
92			}
93			row.Total++
94			if task.Status != nil {
95				switch *task.Status {
96				case "done":
97					row.Done++
98				case "in_progress":
99					row.InProgress++
100				case "blocked":
101					row.Blocked++
102				case "ready":
103					row.Ready++
104				case "todo":
105					row.Todo++
106				}
107			}
108			counts[featureID] = row
109		}
110		out := make([]database2.WorkspaceFeatureTaskCounts, 0, len(featureIDs))
111		for _, featureID := range featureIDs {
112			out = append(out, counts[featureID])
113		}
114		return out, nil
