269	type testAPIEnvelope struct {
270		Success bool            `json:"success"`
271		Data    json.RawMessage `json:"data"`
272		Error   *testAPIError   `json:"error"`
273	}
274	
275	type testAPIError struct {
276		Code      domain.ErrorCode `json:"code"`
277		Message   string           `json:"message"`
278		Retryable bool             `json:"retryable"`
279		Source    string           `json:"source"`
280	}
281	
282	func decodeAPIData[T any](t *testing.T, body []byte) T {
283		t.Helper()
284		var envelope testAPIEnvelope
285		if err := json.Unmarshal(body, &envelope); err != nil {
286			t.Fatalf("decode response envelope: %v", err)
287		}
288		if !envelope.Success {
289			t.Fatalf("expected success envelope, got body=%s", string(body))
290		}
291		if envelope.Error != nil {
292			t.Fatalf("did not expect error field in success envelope: %+v", envelope.Error)
293		}
294		var out T
295		if err := json.Unmarshal(envelope.Data, &out); err != nil {
296			t.Fatalf("decode response data: %v", err)
297		}
298		return out
299	}
300	
301	func decodeAPIError(t *testing.T, body []byte) testAPIError {
302		t.Helper()
303		var envelope testAPIEnvelope
304		if err := json.Unmarshal(body, &envelope); err != nil {
305			t.Fatalf("decode error envelope: %v", err)
306		}
307		if envelope.Success {
308			t.Fatalf("expected error envelope, got body=%s", string(body))
309		}
310		if envelope.Error == nil {
311			t.Fatalf("expected error body, got body=%s", string(body))
312		}
313		return *envelope.Error
314	}
