335	func TestPublicResponseEnvelope_SuccessAndError(t *testing.T) {
336		ws := makeTestWorkspace()
337		r := newTestRouter(&fakeDB{workspaces: []database2.Workspace{ws}}, &fakeAdapter{})
338	
339		successRecorder := httptest.NewRecorder()
340		successReq, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces", nil)
341		r.ServeHTTP(successRecorder, successReq)
342	
343		var successBody map[string]json.RawMessage
344		if err := json.Unmarshal(successRecorder.Body.Bytes(), &successBody); err != nil {
345			t.Fatalf("decode success envelope: %v", err)
346		}
347		if got := string(successBody["success"]); got != "true" {
348			t.Fatalf("expected success=true envelope, got %s body=%s", got, successRecorder.Body.String())
349		}
350		if _, ok := successBody["data"]; !ok {
351			t.Fatalf("expected success response to include data: %s", successRecorder.Body.String())
352		}
353		if _, ok := successBody["error"]; ok {
354			t.Fatalf("did not expect error field in success response: %s", successRecorder.Body.String())
355		}
356	
357		errorRecorder := httptest.NewRecorder()
358		errorReq, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces/99999999-9999-9999-9999-999999999999/activity", nil)
359		r.ServeHTTP(errorRecorder, errorReq)
360	
361		var errorBody struct {
362			Success bool `json:"success"`
363			Error   struct {
364				Code      domain.ErrorCode `json:"code"`
365				Message   string           `json:"message"`
366				Retryable bool             `json:"retryable"`
367				Source    string           `json:"source"`
368			} `json:"error"`
369		}
370		if err := json.Unmarshal(errorRecorder.Body.Bytes(), &errorBody); err != nil {
371			t.Fatalf("decode error envelope: %v", err)
372		}
373		if errorBody.Success {
374			t.Fatalf("expected success=false error envelope: %s", errorRecorder.Body.String())
375		}
376		if errorBody.Error.Code != domain.ErrDatabaseNotFound {
377			t.Fatalf("expected error code %s, got %s", domain.ErrDatabaseNotFound, errorBody.Error.Code)
378		}
379		if errorBody.Error.Message == "" {
380			t.Fatal("expected error message")
381		}
382		var rawError map[string]json.RawMessage
383		if err := json.Unmarshal(errorRecorder.Body.Bytes(), &rawError); err != nil {
384			t.Fatalf("decode raw error envelope: %v", err)
385		}
386		var errorFields map[string]json.RawMessage
387		if err := json.Unmarshal(rawError["error"], &errorFields); err != nil {
388			t.Fatalf("decode raw error body: %v", err)
389		}
390		if _, ok := errorFields["source"]; !ok {
391			t.Fatalf("expected public error source field: %s", errorRecorder.Body.String())
392		}
393		if errorBody.Error.Source != string(domain.ErrorSourceDatabase) {
394			t.Fatalf("expected error source %q, got %q", domain.ErrorSourceDatabase, errorBody.Error.Source)
395		}
396	}
