	for _, task := range f.tasks {
		if database2.UUIDString(task.FeatureID) == featureID {
			out = append(out, task)
		}
	}
	return out, nil
}
func (f *fakeDB) SearchFeatureTasks(_ context.Context, _, featureID string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error) {
	out := make([]database2.WorkspaceTask, 0, len(f.tasks))
	for _, task := range f.tasks {
		if database2.UUIDString(task.FeatureID) != featureID {
			continue
		}
		if filters.Title != "" && task.Title != filters.Title {
			continue
		}
		if filters.Status != "" && (task.Status == nil || *task.Status != filters.Status) {
			continue
		}
		out = append(out, task)
	}
	if filters.Limit > 0 && filters.Limit < len(out) {
		out = out[:filters.Limit]
	}
	return out, nil
}
func (f *fakeDB) SearchWorkspaceTasks(_ context.Context, _ string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error) {
	out := make([]database2.WorkspaceTask, 0, len(f.tasks))
	for _, task := range f.tasks {
		if filters.TaskID != "" && !strings.Contains(strings.ToLower(task.TaskName), strings.ToLower(filters.TaskID)) {
			continue
		}
		if filters.Title != "" && !strings.Contains(strings.ToLower(task.Title), strings.ToLower(filters.Title)) {
			continue
		}
		if filters.Status != "" && (task.Status == nil || *task.Status != filters.Status) {
			continue
		}
		if filters.Repo != "" && (task.Repo == nil || *task.Repo != filters.Repo) {
			continue
		}
		out = append(out, task)
	}
	if filters.Limit > 0 && filters.Limit < len(out) {
		out = out[:filters.Limit]
	}
	return out, nil
}
func (f *fakeDB) ListWorkspaceTasks(_ context.Context, _ string) ([]database2.WorkspaceTask, error) {
	return f.tasks, nil
}

func (f *fakeDB) GetWorkspaceTask(_ context.Context, _, featureID, taskID string) (database2.WorkspaceTask, error) {
	for _, t := range f.tasks {
		if database2.UUIDString(t.FeatureID) == featureID && database2.UUIDString(t.TaskID) == taskID {
			return t, nil
		}
	}
	return database2.WorkspaceTask{}, database2.ErrNotFound
}

func (f *fakeDB) GetWorkspaceTaskByID(_ context.Context, workspaceID, taskID string) (database2.WorkspaceTask, error) {
	for _, t := range f.tasks {
		if database2.UUIDString(t.WorkspaceID) == workspaceID && database2.UUIDString(t.TaskID) == taskID {
			return t, nil
		}
	}
	return database2.WorkspaceTask{}, database2.ErrNotFound
}

func (f *fakeDB) ListActivityEvents(_ context.Context, _, _, _ string) ([]database2.WorkspaceActivityEvent, error) {
	return f.activity, nil
}

func (f *fakeDB) CountWorkspaceFeatures(_ context.Context, _ string, _ database2.FeatureSearchFilters) (int, error) {
	return len(f.features), nil
}

func (f *fakeDB) CountFeatureTasks(_ context.Context, _, featureID string, _ database2.TaskSearchFilters) (int, error) {
	count := 0
	for _, t := range f.tasks {
		if database2.UUIDString(t.FeatureID) == featureID {
			count++
		}
	}
	return count, nil
}

func (f *fakeDB) CountWorkspaceTasks(_ context.Context, _ string, _ database2.TaskSearchFilters) (int, error) {
	return len(f.tasks), nil
}

type fakeAdapter struct {
	importID  string
	importErr error
	syncErr   error
}

func (f *fakeAdapter) ImportWorkspace(_ context.Context, _ adapter.ImportRequest) (string, error) {
	return f.importID, f.importErr
}
func (f *fakeAdapter) SyncWorkspace(_ context.Context, _ string) error {
	return f.syncErr
}

// --- setup helpers ---

func makeTestWorkspace() database2.Workspace {
	var ws database2.Workspace
	_ = ws.ID.Scan(handlerTestWSID)
	ws.Name = "Test Workspace"
	ws.Slug = "test-workspace"
	_ = ws.UpdatedAt.Scan(time.Now())
	return ws
}

func makeSuccessfulSyncRun(workspaceID string) database2.WorkspaceSyncRun {
	var run database2.WorkspaceSyncRun
	_ = run.ID.Scan("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa")
	_ = run.WorkspaceID.Scan(workspaceID)
	run.Trigger = "api_import"
	run.Mode = "full"
	run.Status = "success"
	_ = run.StartedAt.Scan(time.Now().Add(-time.Second))
	_ = run.FinishedAt.Scan(time.Now())
	return run
}

func newTestRouter(db service.DatabaseReader, adp service.AdapterCaller) *gin.Engine {
	gin.SetMode(gin.TestMode)
	svc := service.New(db, adp, 30*time.Minute)
	h := handler.New(svc)
	r := gin.New()
	api := r.Group("/api")
	h.RegisterRoutes(api)
	return r
}

// --- tests ---

type testAPIEnvelope struct {
	Success bool            `json:"success"`
	Data    json.RawMessage `json:"data"`
	Error   *testAPIError   `json:"error"`
}

type testAPIError struct {
	Code      domain.ErrorCode `json:"code"`
	Message   string           `json:"message"`
	Retryable bool             `json:"retryable"`
	Source    string           `json:"source"`
}

func decodeAPIData[T any](t *testing.T, body []byte) T {
	t.Helper()
	var envelope testAPIEnvelope
	if err := json.Unmarshal(body, &envelope); err != nil {
		t.Fatalf("decode response envelope: %v", err)
	}
	if !envelope.Success {
		t.Fatalf("expected success envelope, got body=%s", string(body))
	}
	if envelope.Error != nil {
		t.Fatalf("did not expect error field in success envelope: %+v", envelope.Error)
	}
	var out T
	if err := json.Unmarshal(envelope.Data, &out); err != nil {
		t.Fatalf("decode response data: %v", err)
	}
	return out
}

func decodeAPIError(t *testing.T, body []byte) testAPIError {
	t.Helper()
	var envelope testAPIEnvelope
	if err := json.Unmarshal(body, &envelope); err != nil {
		t.Fatalf("decode error envelope: %v", err)
	}
	if envelope.Success {
		t.Fatalf("expected error envelope, got body=%s", string(body))
	}
	if envelope.Error == nil {
		t.Fatalf("expected error body, got body=%s", string(body))
	}
	return *envelope.Error
}

func TestListWorkspaces_200(t *testing.T) {
	ws := makeTestWorkspace()
	db := &fakeDB{workspaces: []database2.Workspace{ws}}
	r := newTestRouter(db, &fakeAdapter{})

	w := httptest.NewRecorder()
	req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces", nil)
	r.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", w.Code, w.Body.String())
	}

	result := decodeAPIData[[]domain.WorkspaceSummary](t, w.Body.Bytes())
	if len(result) != 1 {
		t.Errorf("expected 1 workspace, got %d", len(result))
	}
}

func TestPublicResponseEnvelope_SuccessAndError(t *testing.T) {
	ws := makeTestWorkspace()
	r := newTestRouter(&fakeDB{workspaces: []database2.Workspace{ws}}, &fakeAdapter{})

	successRecorder := httptest.NewRecorder()
	successReq, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces", nil)
	r.ServeHTTP(successRecorder, successReq)

	var successBody map[string]json.RawMessage
	if err := json.Unmarshal(successRecorder.Body.Bytes(), &successBody); err != nil {
		t.Fatalf("decode success envelope: %v", err)
	}
	if got := string(successBody["success"]); got != "true" {
		t.Fatalf("expected success=true envelope, got %s body=%s", got, successRecorder.Body.String())
	}
	if _, ok := successBody["data"]; !ok {
		t.Fatalf("expected success response to include data: %s", successRecorder.Body.String())
	}
	if _, ok := successBody["error"]; ok {
		t.Fatalf("did not expect error field in success response: %s", successRecorder.Body.String())
	}

	errorRecorder := httptest.NewRecorder()
	errorReq, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces/99999999-9999-9999-9999-999999999999/activity", nil)
	r.ServeHTTP(errorRecorder, errorReq)

	var errorBody struct {
		Success bool `json:"success"`
		Error   struct {
			Code      domain.ErrorCode `json:"code"`
			Message   string           `json:"message"`
			Retryable bool             `json:"retryable"`
			Source    string           `json:"source"`
		} `json:"error"`
	}
	if err := json.Unmarshal(errorRecorder.Body.Bytes(), &errorBody); err != nil {
		t.Fatalf("decode error envelope: %v", err)
	}
	if errorBody.Success {
		t.Fatalf("expected success=false error envelope: %s", errorRecorder.Body.String())
	}
	if errorBody.Error.Code != domain.ErrDatabaseNotFound {
		t.Fatalf("expected error code %s, got %s", domain.ErrDatabaseNotFound, errorBody.Error.Code)
	}
	if errorBody.Error.Message == "" {
		t.Fatal("expected error message")
	}
	var rawError map[string]json.RawMessage
	if err := json.Unmarshal(errorRecorder.Body.Bytes(), &rawError); err != nil {
		t.Fatalf("decode raw error envelope: %v", err)
	}
	var errorFields map[string]json.RawMessage
	if err := json.Unmarshal(rawError["error"], &errorFields); err != nil {
		t.Fatalf("decode raw error body: %v", err)
	}
	if _, ok := errorFields["source"]; !ok {
		t.Fatalf("expected public error source field: %s", errorRecorder.Body.String())
