	api := r.Group("/api")
	h.RegisterRoutes(api)
	return r
}

// newAuthTestRouter creates a test router that injects ac into every request context,
// simulating the RequireAuth middleware for handler-level auth tests.
func newAuthTestRouter(db service.DatabaseReader, adp service.AdapterCaller, ac *authmw.AuthCtx) *gin.Engine {
	gin.SetMode(gin.TestMode)
	svc := service.New(db, adp, 30*time.Minute)
	h := handler.New(svc)
	r := gin.New()
	r.Use(func(c *gin.Context) {
		c.Request = c.Request.WithContext(authmw.SetAuthCtx(c.Request.Context(), ac))
		c.Next()
	})
	api := r.Group("/api")
	h.RegisterRoutes(api)
	return r
}

